import hashlib
import json
from pathlib import Path, PureWindowsPath
import re
import yaml

root = Path.cwd()
config_path = root / 'development/ai_settings.yaml'
data = yaml.safe_load(config_path.read_text(encoding='utf-8'))
qualification = json.loads((root / 'testing/reports/qualification/A08-runner/qualification.json').read_text(encoding='utf-8'))
attempts = {a['id']: a for a in qualification['attempts']}
findings = {}
for name, attempt_id, executable in [('sol', 'sol-2', 'codex'), ('opus', 'opus-1', 'claude')]:
    command = data['prep']['readers'][name]['command']
    expected = list(attempts[attempt_id]['argv'])
    expected[0] = executable
    substitutions = {
        '--model': '{model}', '--effort': '{effort}', '--image': '{image}',
        '--output-schema': '{output_schema_file}', '--output-last-message': '{last_message_file}',
        '--settings': '{claude_settings_file}', '--json-schema': '{output_schema_json}',
    }
    for flag, placeholder in substitutions.items():
        if flag in expected:
            expected[expected.index(flag) + 1] = placeholder
    for i, argument in enumerate(expected):
        if argument == 'model_reasoning_effort=max':
            expected[i] = 'model_reasoning_effort={reasoning_effort}'
        elif argument == 'service_tier=fast':
            expected[i] = 'service_tier={service_tier}'
        elif argument.startswith('sqlite_home='):
            expected[i] = 'sqlite_home="{codex_state_dir}"'
        elif argument.startswith('log_dir='):
            expected[i] = 'log_dir="{codex_log_dir}"'
    findings[name] = {
        'qualified_argv_preserved_after_documented_substitutions': command['argv_template'] == expected,
        'no_absolute_path_or_key_like_literal': not re.search(r'(?:[A-Za-z]:[\\/]|sk-[A-Za-z0-9_-]{16,}|https?://)', json.dumps(command)) and all(not Path(a).is_absolute() and not PureWindowsPath(a).is_absolute() for a in command['argv_template']),
        'stdin_prompt': command['prompt_transport'] == 'stdin',
    }
print(json.dumps({'yaml_sha256': hashlib.sha256(config_path.read_bytes()).hexdigest(), 'findings': findings, 'scope': 'Static configuration comparison only; no reader or runtime execution'}))

